#include <cstddef>
#include <iostream>

class Buffer {                       // WRONG: rule of three violated
    int* data_ = nullptr;
    std::size_t n_ = 0;
public:
    explicit Buffer(std::size_t n) : data_(new int[n]{}), n_(n) {}
    ~Buffer() { delete[] data_; }
    // implicit copy: copies the POINTER, not the buffer
    int& at(std::size_t i) { return data_[i]; }
};

int main() {
    Buffer a(4);
    Buffer b = a;                    // shallow copy: b.data_ == a.data_
    b.at(0) = 99;
    std::cout << a.at(0) << '\n';    // 99 - surprise aliasing
}                                    // two delete[] on one pointer: double free (UB)

#include <algorithm>
#include <cstddef>
#include <utility>

class Buffer {
    int* data_ = nullptr;
    std::size_t n_ = 0;
public:
    explicit Buffer(std::size_t n) : data_(new int[n]{}), n_(n) {}
    ~Buffer() { delete[] data_; }

    Buffer(const Buffer& other)                          // deep copy ctor
        : data_(new int[other.n_]), n_(other.n_) {
        std::copy(other.data_, other.data_ + n_, data_);
    }
    Buffer& operator=(const Buffer& other) {             // deep copy assign
        if (this != &other) {
            int* fresh = new int[other.n_];              // secure new data first
            std::copy(other.data_, other.data_ + other.n_, fresh);
            delete[] data_;                              // only then release old
            data_ = fresh;
            n_ = other.n_;
        }
        return *this;
    }
    Buffer(Buffer&& other) noexcept                      // move ctor: steal
        : data_(std::exchange(other.data_, nullptr)),
          n_(std::exchange(other.n_, 0)) {}
    Buffer& operator=(Buffer&& other) noexcept {         // move assign
        if (this != &other) {
            delete[] data_;                              // free ours, then steal
            data_ = std::exchange(other.data_, nullptr);
            n_ = std::exchange(other.n_, 0);
        }
        return *this;
    }
};

#include <cstddef>
#include <vector>

class Buffer {                    // rule of zero: nothing declared
    std::vector<int> data_;       // owns its heap buffer via RAII
public:
    explicit Buffer(std::size_t n) : data_(n, 0) {}
    int& at(std::size_t i) { return data_[i]; }
};                                // copies, moves, destruction: all correct, all free

