    A a;
    A b = a;
    b = a;
}

#include <iostream>
#include <utility>
struct B {
    B() = default;
    B(const B&) { std::cout << "C"; }
    B(B&&) noexcept { std::cout << "M"; }
    B& operator=(const B&) { std::cout << "A"; return *this; }
    B& operator=(B&&) noexcept { std::cout << "X"; return *this; }
};
int main() {
    B a;
    B b = a;
    B c = std::move(a);
    b = a;
    b = std::move(c);
